DB_SCHEMA = "\nCREATE TABLE IF NOT EXISTS apis (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    name TEXT NOT NULL,\n    slug TEXT NOT NULL UNIQUE,\n    base_url TEXT NOT NULL,\n    auth_type TEXT DEFAULT 'none',\n    secret_ref TEXT,\n    description TEXT,\n    tags TEXT,\n    enabled INTEGER DEFAULT 1,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL\n);\nCREATE TABLE IF NOT EXISTS endpoints (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    api_id INTEGER NOT NULL,\n    name TEXT NOT NULL,\n    method TEXT NOT NULL,\n    path TEXT NOT NULL,\n    description TEXT,\n    default_headers TEXT,\n    default_query TEXT,\n    default_body TEXT,\n    enabled INTEGER DEFAULT 1,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    FOREIGN KEY(api_id) REFERENCES apis(id)\n);\nCREATE TABLE IF NOT EXISTS request_logs (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    created_at TEXT NOT NULL,\n    api_id INTEGER,\n    endpoint_id INTEGER,\n    method TEXT NOT NULL,\n    url_masked TEXT NOT NULL,\n    status_code INTEGER,\n    response_time_ms INTEGER,\n    success INTEGER,\n    error_summary TEXT,\n    caller TEXT,\n    request_preview TEXT,\n    response_preview TEXT\n);\nCREATE TABLE IF NOT EXISTS secrets (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    name TEXT NOT NULL,\n    key TEXT NOT NULL UNIQUE,\n    value_encrypted TEXT,\n    status TEXT DEFAULT 'missing',\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL\n);\nCREATE TABLE IF NOT EXISTS gateway_routes (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    name TEXT NOT NULL,\n    public_path TEXT NOT NULL UNIQUE,\n    api_id INTEGER NOT NULL,\n    endpoint_id INTEGER,\n    require_token INTEGER DEFAULT 1,\n    rate_limit_per_minute INTEGER DEFAULT 60,\n    enabled INTEGER DEFAULT 1,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    FOREIGN KEY(api_id) REFERENCES apis(id),\n    FOREIGN KEY(endpoint_id) REFERENCES endpoints(id)\n);\nCREATE TABLE IF NOT EXISTS users (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    username TEXT NOT NULL UNIQUE,\n    email TEXT NOT NULL UNIQUE,\n    password_hash TEXT NOT NULL,\n    role TEXT NOT NULL DEFAULT 'developer',\n    status TEXT NOT NULL DEFAULT 'active',\n    usage_reason TEXT,\n    email_verified INTEGER DEFAULT 0,\n    email_verification_token_hash TEXT,\n    email_verification_sent_at TEXT,\n    email_verified_at TEXT,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    last_login_at TEXT\n);\nCREATE TABLE IF NOT EXISTS verification_email_limits (\n    bucket_hash TEXT PRIMARY KEY,\n    window_started_at TEXT NOT NULL,\n    last_sent_at TEXT NOT NULL,\n    send_count INTEGER NOT NULL\n);\nCREATE TABLE IF NOT EXISTS api_keys (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    user_id INTEGER NOT NULL,\n    name TEXT NOT NULL,\n    key_prefix TEXT NOT NULL,\n    key_hash TEXT NOT NULL,\n    status TEXT NOT NULL DEFAULT 'pending',\n    scopes TEXT,\n    allowed_routes TEXT,\n    model_policy TEXT NOT NULL DEFAULT 'all',\n    rate_limit_per_minute INTEGER DEFAULT 60,\n    daily_quota INTEGER DEFAULT 1000,\n    monthly_quota INTEGER DEFAULT 30000,\n    created_at TEXT NOT NULL,\n    approved_at TEXT,\n    revoked_at TEXT,\n    expires_at TEXT,\n    last_used_at TEXT,\n    FOREIGN KEY(user_id) REFERENCES users(id)\n);\nCREATE TABLE IF NOT EXISTS api_key_requests (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    user_id INTEGER NOT NULL,\n    name TEXT NOT NULL,\n    requested_scopes TEXT,\n    requested_reason TEXT,\n    status TEXT NOT NULL DEFAULT 'pending',\n    admin_note TEXT,\n    created_at TEXT NOT NULL,\n    reviewed_at TEXT,\n    reviewed_by INTEGER,\n    FOREIGN KEY(user_id) REFERENCES users(id),\n    FOREIGN KEY(reviewed_by) REFERENCES users(id)\n);\nCREATE TABLE IF NOT EXISTS public_gateway_routes (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    name TEXT NOT NULL,\n    public_path TEXT NOT NULL UNIQUE,\n    target_api_id INTEGER NOT NULL,\n    target_endpoint_id INTEGER,\n    target_method TEXT NOT NULL,\n    target_path TEXT NOT NULL,\n    required_scope TEXT,\n    enabled INTEGER DEFAULT 1,\n    public_docs INTEGER DEFAULT 1,\n    allow_anonymous INTEGER DEFAULT 0,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    FOREIGN KEY(target_api_id) REFERENCES apis(id),\n    FOREIGN KEY(target_endpoint_id) REFERENCES endpoints(id)\n);\nCREATE TABLE IF NOT EXISTS api_usage_logs (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    created_at TEXT NOT NULL,\n    user_id INTEGER,\n    api_key_id INTEGER,\n    route_id INTEGER,\n    method TEXT NOT NULL,\n    public_path TEXT NOT NULL,\n    target_url_masked TEXT,\n    status_code INTEGER,\n    response_time_ms INTEGER,\n    success INTEGER,\n    client_ip_hash TEXT,\n    user_agent_preview TEXT,\n    error_summary TEXT,\n    request_preview TEXT,\n    response_preview TEXT,\n    request_id TEXT,\n    protocol TEXT,\n    model TEXT,\n    streamed INTEGER DEFAULT 0,\n    outcome TEXT,\n    started_at TEXT,\n    completed_at TEXT,\n    first_byte_ms INTEGER,\n    input_tokens INTEGER,\n    output_tokens INTEGER,\n    total_tokens INTEGER,\n    usage_reported INTEGER DEFAULT 0,\n    FOREIGN KEY(user_id) REFERENCES users(id),\n    FOREIGN KEY(api_key_id) REFERENCES api_keys(id),\n    FOREIGN KEY(route_id) REFERENCES public_gateway_routes(id)\n);\nCREATE TABLE IF NOT EXISTS api_key_models (\n    api_key_id INTEGER NOT NULL,\n    model_id TEXT NOT NULL,\n    PRIMARY KEY (api_key_id, model_id),\n    FOREIGN KEY(api_key_id) REFERENCES api_keys(id) ON DELETE CASCADE\n);\n"

LEDGER_SCHEMA = ("CREATE TABLE IF NOT EXISTS credit_wallets (\n        user_id INTEGER PRIMARY KEY REFERENCES users(id),\n        balance_units INTEGER NOT NULL DEFAULT 0 CHECK(typeof(balance_units)='integer' AND balance_units>=0),\n        reserved_units INTEGER NOT NULL DEFAULT 0 CHECK(typeof(reserved_units)='integer' AND reserved_units>=0 AND reserved_units<=balance_units),\n        updated_at TEXT NOT NULL)", "CREATE TABLE IF NOT EXISTS credit_holds (\n        usage_id INTEGER PRIMARY KEY REFERENCES api_usage_logs(id),\n        user_id INTEGER NOT NULL REFERENCES users(id),\n        amount_units INTEGER NOT NULL CHECK(typeof(amount_units)='integer' AND amount_units>=0),\n        status TEXT NOT NULL CHECK(status IN ('held','reconciliation_required','settled','released')),\n        dispatch_state TEXT NOT NULL DEFAULT 'reserved' CHECK(dispatch_state IN ('reserved','dispatched')),\n        dispatched_at TEXT,\n        actual_units INTEGER CHECK(actual_units IS NULL OR (typeof(actual_units)='integer' AND actual_units>=0)),\n        pricing_snapshot TEXT NOT NULL, usage_json TEXT, reason TEXT NOT NULL,\n        created_at TEXT NOT NULL, updated_at TEXT NOT NULL)", "CREATE TABLE IF NOT EXISTS credit_ledger (\n        id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id),\n        reference TEXT NOT NULL UNIQUE, kind TEXT NOT NULL,\n        delta_units INTEGER NOT NULL CHECK(typeof(delta_units)='integer'),\n        delta_reserved_units INTEGER NOT NULL DEFAULT 0 CHECK(typeof(delta_reserved_units)='integer'),\n        balance_after_units INTEGER NOT NULL CHECK(typeof(balance_after_units)='integer' AND balance_after_units>=0),\n        reserved_after_units INTEGER NOT NULL CHECK(typeof(reserved_after_units)='integer' AND reserved_after_units>=0 AND reserved_after_units<=balance_after_units),\n        usage_id INTEGER REFERENCES api_usage_logs(id), actor_id INTEGER REFERENCES users(id),\n        note TEXT NOT NULL, created_at TEXT NOT NULL)", "CREATE TABLE IF NOT EXISTS credit_codes (\n        id INTEGER PRIMARY KEY AUTOINCREMENT, code_hash TEXT NOT NULL UNIQUE, code_tail TEXT NOT NULL,\n        amount_units INTEGER NOT NULL CHECK(typeof(amount_units)='integer' AND amount_units>0),\n        status TEXT NOT NULL CHECK(status IN ('active','redeemed','revoked')),\n        expires_at TEXT, created_at TEXT NOT NULL, created_by INTEGER NOT NULL REFERENCES users(id),\n        note TEXT NOT NULL, issue_reference TEXT NOT NULL UNIQUE,\n        redeemed_by INTEGER REFERENCES users(id), redeemed_at TEXT, revoked_at TEXT)", 'CREATE TABLE IF NOT EXISTS credit_code_attempts (\n        user_id INTEGER PRIMARY KEY REFERENCES users(id), window_started_at TEXT NOT NULL,\n        attempt_count INTEGER NOT NULL CHECK(attempt_count>=0))', 'CREATE TABLE IF NOT EXISTS credit_admin_audit (\n        id INTEGER PRIMARY KEY AUTOINCREMENT, reference TEXT NOT NULL UNIQUE,\n        actor_id INTEGER NOT NULL REFERENCES users(id), action TEXT NOT NULL,\n        user_id INTEGER REFERENCES users(id), usage_id INTEGER REFERENCES api_usage_logs(id),\n        code_id INTEGER REFERENCES credit_codes(id), amount_units INTEGER,\n        reason TEXT NOT NULL, created_at TEXT NOT NULL)', 'CREATE INDEX IF NOT EXISTS idx_credit_holds_user_status ON credit_holds(user_id,status)', 'CREATE INDEX IF NOT EXISTS idx_credit_holds_status_created ON credit_holds(status,created_at)', 'CREATE INDEX IF NOT EXISTS idx_credit_ledger_user_id ON credit_ledger(user_id,id)', "CREATE TRIGGER IF NOT EXISTS credit_ledger_no_update BEFORE UPDATE ON credit_ledger\n        BEGIN SELECT RAISE(ABORT, 'credit ledger is immutable'); END", "CREATE TRIGGER IF NOT EXISTS credit_ledger_no_delete BEFORE DELETE ON credit_ledger\n        BEGIN SELECT RAISE(ABORT, 'credit ledger is immutable'); END", "CREATE TRIGGER IF NOT EXISTS credit_audit_no_update BEFORE UPDATE ON credit_admin_audit\n        BEGIN SELECT RAISE(ABORT, 'credit audit is immutable'); END", "CREATE TRIGGER IF NOT EXISTS credit_audit_no_delete BEFORE DELETE ON credit_admin_audit\n        BEGIN SELECT RAISE(ABORT, 'credit audit is immutable'); END")
